const envelope = $input.first().json;
const raw = envelope.body ?? envelope;
const payload = raw.payload && typeof raw.payload === 'object' ? raw.payload : {};
const plan = payload.plan && typeof payload.plan === 'object' ? payload.plan : null;
const forbidden = /(password|secret|token|authorization|api[_-]?key|cookie|credential)/i;
const flagged = [];
function scan(value, path = 'body') {
  if (!value || typeof value !== 'object') return;
  for (const [key, nested] of Object.entries(value)) {
    const next = `${path}.${key}`;
    if (forbidden.test(key)) flagged.push(next);
    if (nested && typeof nested === 'object') scan(nested, next);
  }
}
scan(raw);
const errors = [];
if (!plan) errors.push('plan is required');
if (plan && (!plan.lastSession || !plan.recovery || !plan.prescription)) errors.push('plan must include lastSession, recovery and prescription');
if (flagged.length) errors.push('credential-like fields are forbidden');
const requestId = String(raw.requestId ?? `progression-${Date.now()}`);
let hash = 2166136261;
for (const char of `${requestId}:${plan?.currentVersion ?? 0}`) { hash ^= char.charCodeAt(0); hash = Math.imul(hash, 16777619); }
return [{ json: { valid: errors.length === 0, errors, requestId, plan, correlationId: `af_progression_${requestId}`.replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 100), idempotencyKey: `progression-${(hash >>> 0).toString(16)}`, mode: 'portfolio-sandbox' } }];

const ctx = $input.first().json;
const plan = ctx.plan;
const last = plan.lastSession;
const recovery = plan.recovery;
const weekFour = Number(plan.weekNumber) % 4 === 0;
const veryHard = Number(last.rpe) >= 9.5;
const lowSleep = Number(recovery.averageSleepHours) < 6.5;
const highFatigue = Number(recovery.fatigueScore) >= 8;
const riskySignals = [weekFour, veryHard, lowSleep, highFatigue].filter(Boolean).length;
let action = 'progress';
let factor = 1;
let reps = Number(last.reps) + 1;
let targetRpe = 8;
let rationale = 'Performance is within the planned range, so the next session can progress conservatively.';
if (weekFour && (veryHard || lowSleep || highFatigue)) {
  action = 'deload'; factor = 0.90; reps = Math.max(8, Math.round(Number(last.reps) * 0.6)); targetRpe = 6.5;
  rationale = `Week ${plan.weekNumber} is a planned deload point and recovery signals are elevated. Reduce load and volume before the next progression block.`;
} else if (veryHard || highFatigue) {
  action = 'hold'; factor = 1; reps = Math.max(8, Number(last.reps)); targetRpe = 7.5;
  rationale = 'The last session was too demanding for a load increase. Hold the prescription and reassess after recovery improves.';
}
const roundStep = (value) => Math.round(value / 2.5) * 2.5;
const targetWeightKg = roundStep(Number(last.weightKg) * factor);
const prescription = { exercise: plan.prescription.exercise, weightKg: targetWeightKg, reps, targetRpe, note: action === 'deload' ? 'Planned deload: reduce intensity and volume, then reassess.' : action === 'hold' ? 'Consolidate technique and recovery before progressing.' : 'Progress using the approved double-progression policy.' };
const checks = [];
if (weekFour) checks.push('week-four deload window');
if (veryHard) checks.push(`high RPE ${last.rpe}`);
if (lowSleep) checks.push(`low average sleep ${recovery.averageSleepHours}h`);
if (highFatigue) checks.push(`fatigue ${recovery.fatigueScore}/10`);
return [{ json: { ...ctx, action, targetWeightKg, targetReps: reps, targetRpe, prescription, rationale, checks, riskySignals } }];

const ctx = $input.first().json;
const actionLabel = ctx.action === 'deload' ? 'A deload week is recommended' : ctx.action === 'hold' ? 'Hold the current prescription' : 'Progress the next session';
const explanation = `${actionLabel}. ${ctx.rationale} This recommendation is produced by explicit rules, not an automatic plan change; a qualified professional must approve the next version.`;
const proposal = {
  scenario: 'adaptation', contractVersion: '1.0',
  outcome: `${ctx.action === 'deload' ? 'A safer recovery week' : 'A reviewed next session'} is ready for approval`,
  explanation,
  businessRules: ['deterministic progression policy', 'recovery signals are contextual', 'no automatic plan publishing', 'optimistic version check', 'human approval required'],
  proposedAction: { action: ctx.action, targetWeightKg: ctx.targetWeightKg, targetReps: ctx.targetReps, targetRpe: ctx.targetRpe, expectedPlanVersion: Number(ctx.plan.currentVersion), prescription: ctx.prescription, checks: ctx.checks }
};
return [{ json: { ok: true, project: 'ActiveFlow', scenario: 'adaptation', status: 'awaiting_human_approval', requestId: ctx.requestId, correlationId: ctx.correlationId, idempotencyKey: ctx.idempotencyKey, message: 'A version-checked plan proposal was created. The current plan is unchanged.', proposal, audit: { correlationId: ctx.correlationId, idempotencyKey: ctx.idempotencyKey, timestamp: new Date().toISOString(), externalWrites: 0, companySystemsContacted: 0 }, portfolioSafety: { syntheticData: true, proprietaryCode: false, companyEndpoints: false, credentials: false } } }];
